from __future__ import annotations

from decimal import Decimal


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric(value: object) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    updated_account = account.copy()

    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    if _numeric(account.get("CRED_LIMIT", "")) <= 0:
        raise BusinessRuleViolation(
            "E1004",
            "Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    return updated_account, [
        {
            "code": "CRED_HOLD_OFF",
            "entity_id": str(account.get("ACCT_ID", "")),
        }
    ]
